<script setup lang="ts">
import { ref } from 'vue';
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { ArrowLeft, Clock, MapPin, Navigation, Save, CalendarDays } from '@lucide/vue';
import AppLayout from '@/Layouts/AppLayout.vue';
import OfficeLocationMap from '@/Components/OfficeLocationMap.vue';

const props=defineProps<{settings:any}>();const page=usePage<any>();
const form=useForm({start_time:props.settings.start_time,end_time:props.settings.end_time||'',grace_minutes:props.settings.grace_minutes,annual_leave_days:props.settings.annual_leave_days,office_latitude:props.settings.office_latitude as number|null,office_longitude:props.settings.office_longitude as number|null,office_radius_meters:props.settings.office_radius_meters});
const locating=ref(false),locationError=ref('');
const locate=()=>{
    locationError.value='';if(!navigator.geolocation){locationError.value='GPS tidak tersedia pada perangkat ini.';return;}
    locating.value=true;navigator.geolocation.getCurrentPosition(p=>{form.office_latitude=Number(p.coords.latitude.toFixed(7));form.office_longitude=Number(p.coords.longitude.toFixed(7));locating.value=false;},()=>{locationError.value='Lokasi tidak dapat diperoleh. Aktifkan izin GPS, pilih pin pada peta, atau isi koordinat.';locating.value=false;},{enableHighAccuracy:true,timeout:15000,maximumAge:0});
};
const save=()=>form.put('/dashboard/pegawai/absensi/settings',{preserveScroll:true});
</script>
<template><Head title="Pengaturan Absensi"/><AppLayout><main class="attendance-settings mx-auto max-w-[1500px] space-y-5 p-4 sm:p-6">
<Link href="/dashboard/pegawai/absensi" class="inline-flex items-center gap-2 text-sm font-semibold text-amber-900"><ArrowLeft class="h-4 w-4"/>Kembali ke Absensi</Link>
<div class="flex flex-wrap items-center justify-between gap-4"><div><p class="eyebrow">MANAJEMEN KARYAWAN</p><h1>Pengaturan Absensi</h1><p class="muted mt-2">Kelola jam kantor, cuti tahunan, serta lokasi dan radius absen Office.</p></div><button type="submit" form="attendance-settings-form" class="save-action action-save" :disabled="form.processing"><Save class="h-4 w-4"/>{{ form.processing?'Menyimpan...':'Simpan Pengaturan' }}</button></div>
<p v-if="page.props.flash?.success" role="status" class="notice">{{ page.props.flash.success }}</p><div v-if="form.hasErrors" role="alert" class="errors">{{ Object.values(form.errors).join(' ') }}</div>
<form id="attendance-settings-form" class="grid min-w-0 items-start gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(0,1.3fr)]" @submit.prevent="save">
<div class="min-w-0 space-y-5"><section class="panel"><h2><Clock class="h-5 w-5"/>Jam Kerja Kantor</h2><p class="muted mt-2 text-sm">Pengaturan ini digunakan bersama oleh absensi, KPI, dan perhitungan potongan payroll.</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label>Jam Masuk Kantor<input v-model="form.start_time" type="time" required/></label><label>Jam Pulang Kantor<input v-model="form.end_time" type="time" :min="form.start_time"/></label><label class="sm:col-span-2">Toleransi Keterlambatan (menit)<input v-model.number="form.grace_minutes" type="number" min="0" max="1440" required/></label></div><p class="hint mt-4">Terhitung terlambat setelah jam masuk dan toleransi terlewati. Lembur tetap melalui pengajuan dan persetujuan.</p></section>
<section class="panel"><h2><CalendarDays class="h-5 w-5"/>Cuti Tahunan</h2><label class="mt-5 block">Jumlah Cuti dalam Setahun (hari)<input v-model.number="form.annual_leave_days" type="number" min="0" max="366" required/></label><p class="muted mt-3 text-sm">Kuota tahunan yang ditetapkan kantor untuk pegawai.</p></section></div>
<section class="panel min-w-0"><h2><MapPin class="h-5 w-5"/>Lokasi Office & Radius Absensi</h2><p class="muted mt-2 text-sm">Klik peta untuk memasang pin, geser pin untuk memperbaiki posisi, atau gunakan lokasi perangkat saat berada di kantor.</p><div class="my-4 flex flex-wrap gap-2"><button type="button" class="action-secondary" :disabled="locating" @click="locate"><Navigation class="h-4 w-4"/>{{ locating?'Mencari lokasi...':'Gunakan Lokasi Saya' }}</button><button v-if="form.office_latitude!==null || form.office_longitude!==null" type="button" class="action-secondary" @click="form.office_latitude=null;form.office_longitude=null">Hapus Pin</button></div><p v-if="locationError" role="alert" class="errors mb-3">{{ locationError }}</p>
<OfficeLocationMap v-model:latitude="form.office_latitude" v-model:longitude="form.office_longitude" :radius="form.office_radius_meters"/>
<div class="mt-4 grid gap-4 sm:grid-cols-2"><label>Latitude Kantor<input v-model.number="form.office_latitude" type="number" step="any" min="-90" max="90" placeholder="Pilih pin pada peta"/></label><label>Longitude Kantor<input v-model.number="form.office_longitude" type="number" step="any" min="-180" max="180" placeholder="Pilih pin pada peta"/></label><label class="sm:col-span-2">Radius Absensi Office (meter)<input v-model.number="form.office_radius_meters" type="number" min="1" max="10000" required/></label></div>
<p class="hint mt-4">Radius awal 10 meter. Absen Office di luar radius ditolak dengan peringatan: “Anda tidak berada di sekitar kantor”. Pin dan radius harus disimpan terlebih dahulu.</p><p v-if="form.office_latitude===null || form.office_longitude===null" class="mt-3 text-sm font-semibold text-amber-900">Pin kantor belum ditentukan. Absen Office belum dapat diverifikasi.</p>
</section></form>
</main></AppLayout></template>
<style scoped>
.attendance-settings{color:#292c2d}.eyebrow{font-size:11px;letter-spacing:.15em;font-weight:700;color:#806329}.attendance-settings h1{font-family:Georgia,serif;font-weight:700;font-size:30px}.panel{min-width:0;background:#fffcf6;border:1px solid #e5d8c0;border-radius:18px;padding:24px;box-shadow:0 6px 24px #292c2d0b}.panel h2{display:flex;align-items:center;gap:9px;font-family:Georgia,serif;font-size:20px;font-weight:700}.panel h2 svg{color:#806329}.muted{color:#68645c}.attendance-settings label{font-size:14px;font-weight:600}.attendance-settings input{display:block;min-width:0;width:100%;min-height:46px;background:#fff;border:1px solid #d6c8b1;border-radius:10px;padding:10px;margin-top:7px;color:#292c2d}.action-save,.action-secondary{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 16px;border-radius:10px;font-size:14px;font-weight:700}.action-save{background:#15803d;color:white}.action-save:hover{background:#166534}.action-secondary{background:#fff;border:1px solid #ad8a4c;color:#71551c}.hint{padding:12px;border-radius:10px;background:#f5eddd;font-size:13px;line-height:1.6;color:#655431}.notice{padding:12px;border:1px solid #b4d7be;border-radius:10px;background:#eaf6ed;color:#236438}.errors{padding:12px;border-radius:10px;background:#fff0ed;color:#a33624}.attendance-settings :is(button,input):focus-visible{outline:3px solid #c8ad7f;outline-offset:2px}.attendance-settings button:disabled{opacity:.6}@media(max-width:600px){.panel{padding:18px}.attendance-settings h1{font-size:26px}}
</style>
